DECLARE
  v_request record;
BEGIN
  -- 1. Identify the request
  SELECT * INTO v_request FROM follow_requests WHERE id = p_request_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Request not found';
  END IF;

  -- 2. Verify current user is the one being followed
  IF v_request.followed_id <> auth.uid() THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- 3. Insert into user_follows ignoring conflicts
  INSERT INTO user_follows (user_id, followed_user_id) 
  VALUES (v_request.follower_id, v_request.followed_id)
  ON CONFLICT (user_id, followed_user_id) DO NOTHING;

  -- 4. Delete the original notification for the followed user (clean up inbox)
  DELETE FROM public.notifications 
  WHERE user_id = v_request.followed_id 
    AND actor_id = v_request.follower_id 
    AND type = 'follow_request';

  -- 5. Notify the requester that their petition was accepted
  INSERT INTO public.notifications (user_id, actor_id, type)
  VALUES (v_request.follower_id, v_request.followed_id, 'follow_accepted');

  -- 6. DELETE the request record
  DELETE FROM follow_requests WHERE id = p_request_id;
END;

