DECLARE
  v_user_id       UUID := auth.uid();
  v_is_area_admin BOOLEAN;
  v_balance       JSONB;
  v_available     NUMERIC(10,2);
  v_total_calc    NUMERIC(10,2) := 0;
  v_req_id        BIGINT;
  v_item          RECORD;
  v_mat_price     NUMERIC(10,2);
  v_mat_active    BOOLEAN;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM area_admins WHERE area_id = p_area_id AND user_id = v_user_id
  ) OR is_user_admin(v_user_id) INTO v_is_area_admin;

  IF NOT v_is_area_admin THEN
    RAISE EXCEPTION 'User is not an admin of this area';
  END IF;

  v_balance := get_area_balance(p_area_id);
  v_available := (v_balance->>'availableBalance')::NUMERIC;

  INSERT INTO area_material_requests (area_id, user_id, status, total_amount, notes)
  VALUES (p_area_id, v_user_id, 'pending', 0, p_notes)
  RETURNING id INTO v_req_id;

  FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(material_id BIGINT, quantity INT)
  LOOP
    SELECT price, active INTO v_mat_price, v_mat_active
    FROM material_catalog WHERE id = v_item.material_id;

    IF v_mat_price IS NULL OR NOT v_mat_active THEN
      RAISE EXCEPTION 'Invalid or inactive material item: %', v_item.material_id;
    END IF;

    IF v_item.quantity <= 0 THEN
      RAISE EXCEPTION 'Quantity must be positive';
    END IF;

    INSERT INTO area_material_request_items (request_id, material_id, quantity, unit_price)
    VALUES (v_req_id, v_item.material_id, v_item.quantity, v_mat_price);

    v_total_calc := v_total_calc + (v_mat_price * v_item.quantity);
  END LOOP;

  IF v_total_calc > v_available THEN
    RAISE EXCEPTION 'Request total (%) exceeds available balance (%)', v_total_calc, v_available;
  END IF;

  UPDATE area_material_requests 
  SET total_amount = v_total_calc 
  WHERE id = v_req_id;

  RETURN v_req_id;
END;

DECLARE
  existing_room_id uuid;
  new_room_id uuid;
  current_user_id uuid := auth.uid();
BEGIN
  IF current_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF other_user_id IS NULL OR other_user_id = current_user_id THEN
    RAISE EXCEPTION 'Invalid recipient';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.user_profiles WHERE id = other_user_id) THEN
    RAISE EXCEPTION 'User not found';
  END IF;

  IF has_message_blocking(current_user_id, other_user_id) THEN
    RAISE EXCEPTION 'Cannot start conversation due to user block';
  END IF;

  SELECT cp1.room_id INTO existing_room_id
  FROM public.chat_participants cp1
  INNER JOIN public.chat_participants cp2 ON cp1.room_id = cp2.room_id
  WHERE cp1.user_id = current_user_id
    AND cp2.user_id = other_user_id
  LIMIT 1;

  IF existing_room_id IS NOT NULL THEN
    RETURN existing_room_id;
  END IF;

  IF NOT is_profile_public(other_user_id) AND NOT EXISTS (
    SELECT 1 FROM public.user_follows
    WHERE user_id = other_user_id AND followed_user_id = current_user_id
  ) THEN
    RAISE EXCEPTION 'Cannot start conversation with a private profile';
  END IF;

  new_room_id := gen_random_uuid();

  INSERT INTO public.chat_rooms (id)
  VALUES (new_room_id);

  INSERT INTO public.chat_participants (room_id, user_id)
  VALUES
    (new_room_id, current_user_id),
    (new_room_id, other_user_id);

  RETURN new_room_id;
END;

DECLARE
    v_center_id UUID := NEW.center_id;
    v_user_id UUID := auth.uid();
    v_is_admin BOOLEAN := is_user_admin(v_user_id) OR is_indoor_center_admin(v_center_id);
    v_is_routesetter BOOLEAN := is_indoor_center_routesetter(v_center_id);
    v_is_creator BOOLEAN := (OLD.user_creator_id IS NOT NULL AND OLD.user_creator_id = v_user_id);
    v_can_edit BOOLEAN;
    v_can_archive BOOLEAN;
BEGIN
    IF v_is_admin OR v_is_routesetter OR v_is_creator THEN
        RETURN NEW;
    END IF;

    v_can_edit := (get_indoor_center_permission(v_center_id, 'can_edit_routes') = 'all');
    v_can_archive := (get_indoor_center_permission(v_center_id, 'can_archive_routes') = 'all');

    IF v_can_edit THEN
        RETURN NEW;
    END IF;

    IF v_can_archive THEN
        IF (NEW.name IS DISTINCT FROM OLD.name OR
            NEW.grade IS DISTINCT FROM OLD.grade OR
            NEW.color IS DISTINCT FROM OLD.color OR
            NEW.climbing_kind IS DISTINCT FROM OLD.climbing_kind OR
            NEW.slug IS DISTINCT FROM OLD.slug OR
