declare
  _ascent jsonb;
  _user_id uuid;
  _is_admin boolean;

  -- Stats
  _inserted_ascents int := 0;
  _skipped_ascents int := 0;
  _created_areas int := 0;
  _created_crags int := 0;
  _created_routes int := 0;

  -- Variables
  _area_name text;
  _area_slug text;
  _area_8a_slug text;
  _area_id bigint;

  _crag_name text;
  _crag_slug text;
  _crag_8a_slug text;
  _crag_id bigint;
  _lat float;
  _lng float;

  _route_name text;
  _route_slug text;
  _route_8a_slug text;
  _route_id bigint;
  _grade int;
  _climbing_kind public.climbing_kind;

  _candidate_crag_slug text;
  _candidate_route_slug text;
  _all_route_8a_slugs text[];
  _all_crag_8a_slugs text[];

  _date date;
  _style public.ascent_type;
  _tries int;
  _rating int;
  _comment text;
  _recommended boolean;

begin
  _user_id := auth.uid();
  _is_admin := is_user_admin(_user_id);

  for _ascent in select * from jsonb_array_elements(ascents)
  loop
    -- Extract Area
    _area_name := _ascent->>'area_name';
    _area_slug := _ascent->>'area_slug';
    _area_8a_slug := _ascent->>'area_8a_slug';

    -- Buscar área en base a slugs de 8a o slug local
    select id into _area_id from areas
    where slug = _area_slug
       or (_area_8a_slug is not null and eight_anu_crag_slugs @> array[_area_8a_slug])
    limit 1;

    -- Si no se encuentra, intentar buscar globalmente por slug para evitar errores de unicidad
    if _area_id is null then
      select id into _area_id from areas where slug = _area_slug limit 1;
    end if;

    if _area_id is null then
      insert into areas (name, slug, eight_anu_crag_slugs, user_creator_id)
      values (_area_name, _area_slug, case when _area_8a_slug is not null then array[_area_8a_slug] else null end, _user_id)
      on conflict (slug) do update set
        eight_anu_crag_slugs = case
          when _area_8a_slug is not null and not (areas.eight_anu_crag_slugs @> array[_area_8a_slug])
          then array_append(areas.eight_anu_crag_slugs, _area_8a_slug)
          else areas.eight_anu_crag_slugs
        end
      returning id into _area_id;

      if _area_id is null then
         select id into _area_id from areas where slug = _area_slug;
      else
         _created_areas := _created_areas + 1;
      end if;
    else
      if _area_8a_slug is not null and not (coalesce(areas.eight_anu_crag_slugs, array[]::text[]) @> array[_area_8a_slug]) then
        update areas
        set eight_anu_crag_slugs = array_append(coalesce(eight_anu_crag_slugs, array[]::text[]), _area_8a_slug)
        where id = _area_id;
      end if;
    end if;

    -- Extract Crag
    _crag_name := coalesce(nullif(trim(_ascent->>'crag_name'), ''), 'General');
    _crag_slug := coalesce(nullif(trim(_ascent->>'crag_slug'), ''), 'general');
    _crag_8a_slug := _ascent->>'crag_8a_slug';
    _lat := (_ascent->>'lat')::float;
    _lng := (_ascent->>'lng')::float;

    -- Buscar sector ÚNICAMENTE en el área actual
    select id into _crag_id from crags
    where area_id = _area_id
      and (
        slug = _crag_slug
        or (_crag_8a_slug is not null and eight_anu_sector_slugs @> array[_crag_8a_slug])
        or (_crag_slug is not null and eight_anu_sector_slugs @> array[_crag_slug])
      )
    limit 1;

    if _crag_id is null then
      _candidate_crag_slug := _crag_slug;
      if exists (select 1 from crags where slug = _candidate_crag_slug) then
        _candidate_crag_slug := _crag_slug || '-' || _area_slug;
        while exists (select 1 from crags where slug = _candidate_crag_slug) loop
          _candidate_crag_slug := _crag_slug || '-' || substr(md5(random()::text), 1, 5);
        end loop;
      end if;

      _all_crag_8a_slugs := array_remove(array[_crag_8a_slug, _crag_slug], null);

      insert into crags (name, slug, area_id, latitude, longitude, eight_anu_sector_slugs, user_creator_id)
      values (_crag_name, _candidate_crag_slug, _area_id, _lat, _lng, case when cardinality(_all_crag_8a_slugs) > 0 then _all_crag_8a_slugs else null end, _user_id)
      returning id into _crag_id;

      _created_crags := _created_crags + 1;
    else
      if _crag_8a_slug is not null or _crag_slug is not null then
        update crags
        set eight_anu_sector_slugs = (
          select array_agg(distinct s)
          from unnest(array_cat(
            coalesce(crags.eight_anu_sector_slugs, array[]::text[]),
            array_remove(array[_crag_8a_slug, _crag_slug], null)
          )) as s
          where s is not null and s <> ''
        )
        where id = _crag_id
          and not (coalesce(crags.eight_anu_sector_slugs, array[]::text[]) @> array_remove(array[_crag_8a_slug, _crag_slug], null));
      end if;
    end if;

    -- Extract Route
    _route_name := _ascent->>'route_name';
    _route_slug := _ascent->>'route_slug';
    _route_8a_slug := _ascent->>'route_8a_slug';
    _grade := (_ascent->>'grade')::int;
    _climbing_kind := (_ascent->>'climbing_kind')::public.climbing_kind;

    -- Intentamos encontrar la vía ÚNICAMENTE en el sector actual (_crag_id)
    select id into _route_id from routes
    where crag_id = _crag_id
      and (
        slug = _route_slug
        or (_route_8a_slug is not null and eight_anu_route_slugs @> array[_route_8a_slug])
        or (_route_slug is not null and eight_anu_route_slugs @> array[_route_slug])
      )
    limit 1;

    if _route_id is null then
      _candidate_route_slug := _route_slug;
      if exists (select 1 from routes where slug = _candidate_route_slug) then
        _candidate_route_slug := _route_slug || '-' || _crag_slug;
        while exists (select 1 from routes where slug = _candidate_route_slug) loop
          _candidate_route_slug := _route_slug || '-' || substr(md5(random()::text), 1, 5);
        end loop;
      end if;

      _all_route_8a_slugs := array_remove(array[_route_8a_slug, _route_slug], null);

      if _ascent ? 'eight_anu_route_slugs' and jsonb_typeof(_ascent->'eight_anu_route_slugs') = 'array' then
        select coalesce(array_agg(distinct elem), _all_route_8a_slugs) into _all_route_8a_slugs
        from (
          select unnest(_all_route_8a_slugs) as elem
          union
          select jsonb_array_elements_text(_ascent->'eight_anu_route_slugs') as elem
        ) s
        where elem is not null and elem <> '';
      end if;

      insert into routes (name, slug, crag_id, grade, climbing_kind, eight_anu_route_slugs, user_creator_id)
      values (_route_name, _candidate_route_slug, _crag_id, _grade, _climbing_kind, case when cardinality(_all_route_8a_slugs) > 0 then _all_route_8a_slugs else null end, _user_id)
      returning id into _route_id;

      _created_routes := _created_routes + 1;
    else
      if _route_8a_slug is not null or _route_slug is not null then
        update routes
        set eight_anu_route_slugs = (
          select array_agg(distinct s)
          from unnest(array_cat(
            coalesce(routes.eight_anu_route_slugs, array[]::text[]),
            array_remove(array[_route_8a_slug, _route_slug], null)
          )) as s
          where s is not null and s <> ''
        )
        where id = _route_id
          and not (coalesce(routes.eight_anu_route_slugs, array[]::text[]) @> array_remove(array[_route_8a_slug, _route_slug], null));
      end if;
    end if;

    -- Extract Ascent Data
    _date := (_ascent->>'date')::date;
    _style := (_ascent->>'style')::public.ascent_type;
    _tries := coalesce((_ascent->>'attempts')::int, (_ascent->>'tries')::int);
    if _tries is null or _tries <= 0 then
      if _style in ('os', 'f') then
        _tries := 1;
      else
        _tries := null;
      end if;
    end if;
    _rating := (_ascent->>'rating')::int;
    _comment := _ascent->>'comment';
    _recommended := (_ascent->>'recommended')::boolean;

    -- Check if ascent exists
    if not exists (select 1 from route_ascents where user_id = _user_id and route_id = _route_id and date = _date) then
       insert into route_ascents (user_id, route_id, date, type, attempts, rate, comment, recommended, grade)
       values (_user_id, _route_id, _date, _style, _tries, _rating, _comment, _recommended, _grade);
       _inserted_ascents := _inserted_ascents + 1;
    else
       _skipped_ascents := _skipped_ascents + 1;
    end if;

  end loop;

  return (
    _inserted_ascents,
    _skipped_ascents,
    _created_areas,
    _created_crags,
    _created_routes
  )::import_8a_ascents_result;
end;

