DECLARE
    _all_slugs text[];
    _duplicate_group record;
BEGIN
    -- 1. Verificación: Solo administradores
    IF NOT is_user_admin(auth.uid()) THEN
        RAISE EXCEPTION 'Only admins can unify areas';
    END IF;

    -- 2. Recolectar slugs
    SELECT array_agg(DISTINCT s)
    INTO _all_slugs
    FROM (
        SELECT unnest(COALESCE(eight_anu_crag_slugs, ARRAY[]::text[])) as s FROM public.areas
        WHERE id = p_target_area_id OR id = ANY(p_source_area_ids)
        UNION
        SELECT slug FROM public.areas WHERE id = ANY(p_source_area_ids)
    ) t;

    -- 3. Mover sectores al área destino
    UPDATE public.crags SET area_id = p_target_area_id WHERE area_id = ANY(p_source_area_ids);

    -- 4. Unificar sectores con el mismo nombre en el área destino
    FOR _duplicate_group IN (
        SELECT array_agg(id ORDER BY id ASC) as ids
        FROM public.crags
        WHERE area_id = p_target_area_id
        GROUP BY lower(name)
        HAVING count(*) > 1
    )
    LOOP
        PERFORM public.unify_crags(
            _duplicate_group.ids[1],
            _duplicate_group.ids[2:array_length(_duplicate_group.ids, 1)],
            (SELECT name FROM public.crags WHERE id = _duplicate_group.ids[1])
        );
    END LOOP;

    -- 5. Actualizar área destino
    UPDATE public.areas
    SET name = COALESCE(NULLIF(p_new_name, ''), name),
        eight_anu_crag_slugs = _all_slugs
    WHERE id = p_target_area_id;

    -- 6. Borrar áreas origen
    DELETE FROM public.areas WHERE id = ANY(p_source_area_ids);
END;

