DECLARE
    _all_slugs text[];
BEGIN
    -- 1. Verificación: Solo administradores
    IF NOT is_user_admin(auth.uid()) THEN
        RAISE EXCEPTION 'Only admins can unify routes';
    END IF;

    -- 2. Recolectar slugs
    SELECT array_agg(DISTINCT s)
    INTO _all_slugs
    FROM (
        SELECT unnest(COALESCE(eight_anu_route_slugs, ARRAY[]::text[])) as s FROM public.routes
        WHERE id = p_target_route_id OR id = ANY(p_source_route_ids)
        UNION
        SELECT slug FROM public.routes WHERE id = ANY(p_source_route_ids)
    ) t;

    -- 3. Limpiar duplicados en tablas con restricciones UNIQUE
    DELETE FROM public.route_likes
    WHERE route_id = ANY(p_source_route_ids)
      AND user_id IN (SELECT user_id FROM public.route_likes WHERE route_id = p_target_route_id);

    DELETE FROM public.route_projects
    WHERE route_id = ANY(p_source_route_ids)
      AND user_id IN (SELECT user_id FROM public.route_projects WHERE route_id = p_target_route_id);

    DELETE FROM public.route_equippers
    WHERE route_id = ANY(p_source_route_ids)
      AND equipper_id IN (SELECT equipper_id FROM public.route_equippers WHERE route_id = p_target_route_id);

    DELETE FROM public.topo_routes
    WHERE route_id = ANY(p_source_route_ids)
      AND topo_id IN (SELECT topo_id FROM public.topo_routes WHERE route_id = p_target_route_id);

    -- 4. Reasignar registros a la vía destino
    UPDATE public.route_ascents SET route_id = p_target_route_id WHERE route_id = ANY(p_source_route_ids);
    UPDATE public.route_likes SET route_id = p_target_route_id WHERE route_id = ANY(p_source_route_ids);
    UPDATE public.route_projects SET route_id = p_target_route_id WHERE route_id = ANY(p_source_route_ids);
    UPDATE public.route_equippers SET route_id = p_target_route_id WHERE route_id = ANY(p_source_route_ids);
    UPDATE public.topo_routes SET route_id = p_target_route_id WHERE route_id = ANY(p_source_route_ids);

    -- 5. Actualizar vía destino
    UPDATE public.routes
    SET name = COALESCE(NULLIF(p_new_name, ''), name),
        eight_anu_route_slugs = _all_slugs
    WHERE id = p_target_route_id;

    -- 6. Borrar origen
    DELETE FROM public.routes WHERE id = ANY(p_source_route_ids);
END;

DECLARE
    item RECORD;
BEGIN
    IF (TG_OP = 'UPDATE' AND NEW.status = 'paid' AND OLD.status = 'pending') THEN
        FOR item IN 
            SELECT * FROM order_items WHERE order_id = NEW.id AND item_type = 'merchandise'
        LOOP
            IF item.selected_size IS NOT NULL THEN
                UPDATE merchandise_stock
                SET stock = GREATEST(0, stock - COALESCE(item.quantity, 1))
                WHERE item_id = item.item_id AND size = item.selected_size;
            END IF;
        END LOOP;
    ELSIF (TG_OP = 'UPDATE' AND NEW.status IN ('cancelled', 'refunded') AND OLD.status IN ('paid', 'shipped', 'delivered')) THEN
        FOR item IN 
            SELECT * FROM order_items WHERE order_id = NEW.id AND item_type = 'merchandise'
        LOOP
            IF item.selected_size IS NOT NULL THEN
                UPDATE merchandise_stock
                SET stock = stock + COALESCE(item.quantity, 1)
                WHERE item_id = item.item_id AND size = item.selected_size;
            END IF;
        END LOOP;
    END IF;
    RETURN NEW;
END;

DECLARE
    _route_id bigint;
    _ascent_count int;
    _new_grade int;
    _route_ids bigint[];
    _rid bigint;
BEGIN
    -- Determinar qué route_id(s) necesitan actualizarse
    IF TG_OP = 'INSERT' THEN
        _route_ids := ARRAY[NEW.route_id];
    ELSIF TG_OP = 'DELETE' THEN
        _route_ids := ARRAY[OLD.route_id];
    ELSE -- UPDATE
        IF OLD.route_id = NEW.route_id THEN
            _route_ids := ARRAY[NEW.route_id];
        ELSE
            _route_ids := ARRAY[OLD.route_id, NEW.route_id];
        END IF;
    END IF;

    -- Iterar sobre los route_ids afectados (usualmente uno)
    FOREACH _rid IN ARRAY _route_ids LOOP
        -- Contar encadenes totales para esta vía
        SELECT count(*) INTO _ascent_count
        FROM route_ascents
        WHERE route_id = _rid;

        -- Solo actualizar si hay más de 3 encadenes
        IF _ascent_count > 3 THEN
            -- Calcular la mediana (PERCENTILE_DISC devuelve un valor existente del conjunto)
            -- Usamos PERCENTILE_DISC(0.5) para obtener la mediana discreta.
            SELECT PERCENTILE_DISC(0.5) WITHIN GROUP (ORDER BY grade)
            INTO _new_grade
            FROM route_ascents
            WHERE route_id = _rid
              AND type != 'attempt'
              AND grade IS NOT NULL;

            -- Actualizar la vía con el nuevo grado
            IF _new_grade IS NOT NULL THEN
                UPDATE routes
                SET grade = _new_grade
                WHERE id = _rid;
            END IF;
        END IF;
    END LOOP;

    RETURN NULL; -- El valor de retorno se ignora en triggers AFTER
END;

