DECLARE
  v_expected text;
BEGIN
  IF p_secret IS NULL OR length(p_secret) = 0 THEN
    RETURN false;
  END IF;

  SELECT decrypted_secret INTO v_expected
  FROM vault.decrypted_secrets
  WHERE name = 'notify_push_secret'
  LIMIT 1;

  RETURN v_expected IS NOT NULL AND v_expected = p_secret;
END;
